const r = await tools.exec_command({cmd:"python3 - <<'PY'
from pypdf import PdfReader
import re
p='/app/paper.pdf'; r=PdfReader(p)
print('pages',len(r.pages))
terms=re.compile(r'decod|motion energy|tracked across|526|calcium event|20 min|30 Hz|ridge|variance|R[²2]|coefficient of determination',re.I)
for i,page in enumerate(r.pages):
 text=page.extract_text() or ''
 if terms.search(text):
  print(f'\n===== PAGE {i+1} =====')
  lines=text.splitlines()
  hits=[j for j,x in enumerate(lines) if terms.search(x)]
  keep=set()
  for j in hits:
   keep.update(range(max(0,j-4),min(len(lines),j+8)))
  last=-2
  for j in sorted(keep):
   if j>last+1: print('...')
   print(lines[j])
   last=j
PY","workdir":"/app","yield_time_ms":30000,"max_output_tokens":60000});
text(r.output);

